name: Agentics Maintenance

on:
  push:
    branches:
      - main
  pull_request:
    branches:
      - main

jobs:
  refactor-duplicate-code:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v2

      - name: Set up Node.js
        uses: actions/setup-node@v2
        with:
          node-version: '14'

      - name: Install dependencies
        run: npm install

      - name: Refactor duplicate code
        run: |
          #!/bin/bash
          set -e

          # Define the paths to the files containing the duplicate code
          FILE1="build-tools/packages/build-cli/src/commands/check/latestVersions.ts"
          FILE2="build-tools/packages/build-cli/src/commands/vnext/check/latestVersions.ts"

          # Compare the files
          if diff "$FILE1" "$FILE2"; then
            echo "Files are identical."
          else
            echo "Files differ. Please review and refactor."
            exit 1
          fi

          # Replace the duplicate code with a common function
          sed -i '/^const stableVersions = allVersions/,/^this.log(`##vso\[task.setvariable variable=shouldDeploy\]${shouldDeploy}`);$/d' "$FILE1"
          sed -i '/^const stableVersions = versionList/,/^this.log(`##vso\[task.setvariable variable=shouldDeploy\]${shouldDeploy}`);$/d' "$FILE2"

          cat <<EOF > common-check-latest-versions.ts
          export async function checkLatestVersion(version: string, versionList: string[], allVersions: string[]): Promise<void> {
            const stableVersions = allVersions.filter((v) => !semver.prerelease(v)).sort(semver.rcompare);

            let shouldDeploy = false;
            for (const v of stableVersions) {
              if (semver.major(v) === semver.major(version)) {
                if (semver.eq(v, version)) {
                  console.log(\`\${version} is the latest stable version\`);
                  shouldDeploy = true;
                } else {
                  console.log(\`\${version} is NOT the latest stable version. A newer stable version exists: \${v}\`);
                  shouldDeploy = false;
                }
                break;
              }
              console.log(\`No stable version exists for major version \${semver.major(version)}.\`);
              console.log(\`\${version} is the latest stable version\`);
              shouldDeploy = true;
              break;
            }

            console.log(\`##vso[task.setvariable variable=shouldDeploy]\${shouldDeploy}\`);
          }
          EOF

          cp common-check-latest-versions.ts "$FILE1"
          cp common-check-latest-versions.ts "$FILE2"

          # Add the new file to git and commit the changes
          git add "$FILE1" "$FILE2" common-check-latest-versions.ts
          git commit -m "Refactor duplicate code for checking latest versions"
          git push origin main
```

